"""Count whitespace-separated words in a text file."""

import argparse
from pathlib import Path


def count_words(path: str | Path) -> int:
    """Return the number of whitespace-separated words in *path*."""
    return len(Path(path).read_text(encoding="utf-8").split())


def main() -> None:
    parser = argparse.ArgumentParser(description="Count words in a text file.")
    parser.add_argument("file", type=Path, help="path to the text file")
    args = parser.parse_args()

    try:
        count = count_words(args.file)
    except (OSError, UnicodeError) as error:
        parser.error(str(error))
    print(count)


if __name__ == "__main__":
    main()
