cat > test_word_count.py <<'PY'
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

from word_count import count_words


class CountWordsTests(unittest.TestCase):
    def test_counts_whitespace_separated_words(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "sample.txt"
            path.write_text("one\t two\nthree  ", encoding="utf-8")
            self.assertEqual(count_words(path), 3)

    def test_empty_file_has_zero_words(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "empty.txt"
            path.write_text(" \n\t", encoding="utf-8")
            self.assertEqual(count_words(path), 0)

    def test_command_line_prints_count(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "sample.txt"
            path.write_text("hello, world!", encoding="utf-8")
            result = subprocess.run(
                [sys.executable, "word_count.py", str(path)],
                capture_output=True,
                text=True,
                check=True,
            )
            self.assertEqual(result.stdout, "2\n")


if __name__ == "__main__":
    unittest.main()
